-- Generated by sail-lsp install; requires Neovim 0.11 or newer.
vim.filetype.add({ extension = { sail = "sail", sail_project = "sail_project", ["sail-preview"] = "sail_preview" }, filename = { ["sail.proj"] = "sail_project" } })
vim.lsp.config("sail_lsp_managed", {
  cmd = { @SERVER_JSON@ },
  filetypes = { "sail", "sail_project" },
  root_dir = function(buffer, on_dir)
    local directory = vim.fs.dirname(vim.api.nvim_buf_get_name(buffer))
    local marker = vim.fs.find(function(name)
      return name == "sail.proj" or name:match("%.sail_project$") ~= nil or name == ".git"
    end, { path = directory, upward = true, limit = 1 })[1]
    on_dir(marker and vim.fs.dirname(marker) or directory)
  end,
  single_file_support = true,
  settings = { ["sail-lsp"] = vim.empty_dict() },
  handlers = {
    ["window/showDocument"] = function(err, params, context, config)
      local result = vim.lsp.handlers["window/showDocument"](err, params, context, config)
      if not err and params and params.uri:match("%.sail%-preview$") then
        local buffer = vim.uri_to_bufnr(params.uri)
        -- Keep source links on the server which owns this snapshot, even
        -- though its temporary file is outside the workspace root.
        vim.bo[buffer].filetype = "sail_preview"
        vim.lsp.buf_attach_client(buffer, context.client_id)
        vim.bo[buffer].modifiable = false
        vim.bo[buffer].readonly = true
      end
      return result
    end,
  },
})
vim.lsp.enable("sail_lsp_managed")

-- All entries use the same source actions as Zed and other LSP clients. The
-- server revalidates the selected include instance and project task at execution.
local function sail_actions(command)
  vim.lsp.buf.code_action({
    context = { only = { "source.sail" }, diagnostics = {} },
    filter = function(action)
      return not command or (action.command and action.command.command == command)
    end,
    apply = command == "sail-lsp.server.explain" or command == "sail-lsp.server.preprocess" or command == "sail-lsp.server.explainFormatting"
      or command == "sail-lsp.server.openProject",
  })
end
for name, command in pairs({
  SailActions = false,
  SailExplain = "sail-lsp.server.explain",
  SailFormatInfo = "sail-lsp.server.explainFormatting",
  SailPreprocess = "sail-lsp.server.preprocess",
  SailProject = "sail-lsp.server.openProject",
  SailContext = "sail-lsp.server.selectContext",
  SailTasks = "sail-lsp.server.runTask",
  SailCancelTask = "sail-lsp.server.cancelTask",
}) do
  vim.api.nvim_create_user_command(name, function() sail_actions(command) end,
    { desc = "Sail project, analysis and task actions" })
end
vim.api.nvim_create_user_command("SailSelectProject", function()
  local clients = vim.lsp.get_clients({ bufnr = 0, name = "sail_lsp_managed" })
  local client = clients[1]
  if not client then vim.notify("No Sail language server attached", vim.log.levels.INFO); return end
  client:request("sail-lsp/projectGraph", nil, function(err, entries)
    if err then vim.notify(err.message, vim.log.levels.ERROR); return end
    vim.ui.select(entries or {}, {
      prompt = "Sail analysis project",
      format_item = function(entry) return entry.manifest end,
    }, function(entry)
      if not entry then return end
      local settings = vim.deepcopy(client.settings or {})
      settings["sail-lsp"] = settings["sail-lsp"] or vim.deepcopy(settings)
      local sail = settings["sail-lsp"]
      sail.workspace = sail.workspace or {}
      sail.workspace.activeProject = entry.path
      client.settings = settings
      client:notify("workspace/didChangeConfiguration", { settings = settings })
    end)
  end, 0)
end, { desc = "Select the Sail project used for shared files" })
vim.api.nvim_create_user_command("SailSource", function()
  local buffer = vim.api.nvim_get_current_buf()
  local client = vim.lsp.get_clients({ bufnr = buffer, name = "sail_lsp_managed" })[1]
  if not client then return end
  local position = vim.lsp.util.make_position_params(0, client.offset_encoding).position
  client:request("textDocument/documentLink", { textDocument = { uri = vim.uri_from_bufnr(buffer) } }, function(err, links)
    if err then vim.notify(err.message, vim.log.levels.ERROR); return end
    local function open(link)
      if not link or not link.target then return end
      local uri, line, column = link.target:match("^(.-)#L(%d+),(%d+)$")
      if not uri or not uri:match("^file:") then return end
      local start = { line = tonumber(line) - 1, character = tonumber(column) - 1 }
      vim.lsp.util.show_document({ uri = uri, range = { start = start, ["end"] = start } }, client.offset_encoding, { focus = true })
    end
    for _, link in ipairs(links or {}) do
      local range = link.range
      if (position.line > range.start.line or (position.line == range.start.line and position.character >= range.start.character))
        and (position.line < range["end"].line or (position.line == range["end"].line and position.character <= range["end"].character)) then
        open(link); return
      end
    end
    vim.ui.select(links or {}, { prompt = "Sail source location", format_item = function(link) return link.target end }, open)
  end, buffer)
end, { desc = "Open the source of an analysis/preview segment" })
-- Preview buffers are snapshots. Prevent accidental edits even if the editor
-- allows overriding filesystem permissions; use gd or :SailSource to navigate.
vim.api.nvim_create_autocmd("FileType", {
  pattern = "sail_preview",
  callback = function(event)
    vim.bo[event.buf].modifiable = false
    vim.bo[event.buf].readonly = true
    vim.bo[event.buf].swapfile = false
    vim.keymap.set("n", "gd", "<cmd>SailSource<cr>", { buffer = event.buf, desc = "Open original Sail source" })
  end,
})
